#pragma once
void vp_city_trait_yield_tests(){
    using namespace civ5::runtime;using namespace civ5::saves;constexpr auto vp=TechnologyProfile::vp542;
    RulesDatabase db;db.apply_sql("CREATE TABLE Defines(Name,Value);INSERT INTO Defines VALUES('TRADE_ROUTE_BASE_GOLD',-100),('TRADE_ROUTE_CAPITAL_POP_GOLD_MULTIPLIER',15),('TRADE_ROUTE_CITY_POP_GOLD_MULTIPLIER',110);CREATE TABLE Yields(ID,Type);INSERT INTO Yields VALUES(0,'YIELD_FOOD'),(1,'YIELD_PRODUCTION'),(4,'YIELD_CULTURE'),(6,'YIELD_TOURISM');CREATE TABLE Improvements(ID,Type);INSERT INTO Improvements VALUES(2,'A'),(9,'B');");
    const auto types=db.cache_info_types();auto defines=db.cache_global_defines(GlobalDefineProfile::vp542);auto rules=load_vp_city_trait_yield_rules(db,types);
    check(rules.improvement_slots==10&&rules.yield_slots==7&&rules.yields==std::set<std::int64_t>{0,1,4,6},"Trait rules preserve sparse authored IDs and row spans");
    CustomModOptions options;options.entries["BALANCE_VP"].value=1;ResearchContext players;players.profile=vp;players.players[5].team=9;
    CityYieldContext cities;cities.profile=vp;cities.production=1;auto &p=cities.players[5];p.capital=42;auto &traits=ensure_vp_city_trait_yield_profile(cities);auto &a=traits.players[5];auto &era=traits.eras[5];
    auto &capital=p.cities[42];capital.owner=5;capital.id=42;capital.population=10;capital.we_love_king_turns=0;auto &ca=traits.cities[{5,42}];
    auto &city=p.cities[43];city.owner=5;city.id=43;city.population=3;auto &cb=traits.cities[{5,43}];
    TreasuryContext treasury;treasury.profile=vp;auto &t=treasury.players[5];std::map<std::int64_t,std::int64_t> eras{{9,3}};
    VpCityTraitYieldContext context{rules,players,cities,treasury,eras,defines,options};
    const auto query=[&](std::int64_t y=0){return vp_city_trait_yield(context,capital,y);};const auto local=[&](std::int64_t y=0){return vp_city_trait_yield(context,city,y);};
    a.per_improvement={{9,{{0,-1}}},{2,{{0,1}}},{7,{{6,2}}},{8,{{0,0}}}};a.improvements_built={{2,1},{9,1}};rebuild_vp_trait_improvement_types(cities,5);
    check(a.improvement_types==std::vector<std::int64_t>{2,7,9},"Unsaved improvement cache rebuilds ordered types with any nonzero yield, including negative bonuses");
    era.era_scaling=true;era.fractional_era=4;era.odd_era=true;
    auto q=query();check(q.per_turn.improvements==0,"Positive and negative improvement contributions truncate independently at the shared odd/fractional era scale");
    a.improvements_built[2]=3;check(query().per_turn.improvements==6,"Historic improvement count multiplies before a single truncation per improvement type");
    a.per_improvement[10][0]=2;a.improvements_built[10]=1;check(query().per_turn.improvements==6,"Trait matrix mutation does not silently replace the source derived-list rebuild");
    rebuild_vp_trait_improvement_types(cities,5);check(query().per_turn.improvements==11,"Explicit rebuild adds newly contributing improvement types");
    a.capital_only=true;cb.added[0]=7;check(local().per_turn.improvements==0&&local().per_turn.total==7,"Capital-only gate excludes improvements but preserves saved added traits in other cities");
    a.capital_only=false;check(local().per_turn.total==18,"Non-capital cities receive empire historic improvement bonuses when permitted");
    a.historic[0]=-3;a.historic_events=4;check(query().per_turn.historic==-12&&local().per_turn.historic==0,"Historic events contribute only in capital and retain negative yields");
    constexpr std::int64_t big=4294967300LL;
    const auto route=[&](std::int64_t origin,std::int64_t destination){TradeRouteObservation r;r.origin_owner=origin;r.destination_owner=destination;return r;};
    cities.trade_routes={route(5,big),route(big,5),route(5,7),route(5,5),route(2,3)};
    auto empty=route(5,8);empty.origin_x=empty.origin_y=empty.destination_x=empty.destination_y=-1;cities.trade_routes.push_back(empty);
    auto partial=empty;partial.destination_y=0;partial.destination_owner=9;ensure_vp_trade_route(partial).recalled=true;partial.id=-1;cities.trade_routes.push_back(partial);
    check(vp_different_trade_partners(cities,5)==3,"Trade partners deduplicate both directions, permit wide IDs and ignore internal or fully empty routes only");
    cities.players[7].minor=true;treasury.minor_players.insert(7);players.players[7].alive=false;check(vp_different_trade_partners(cities,5)==3,"Partner counting does not filter minor status, death, recalled routes or route IDs");
    a.per_partner[0]=2;check(query().per_turn.partners==18&&local().per_turn.partners==0,"Capital positive partner trait scales distinct trading players by team era");
    eras[9]=0;check(query().per_turn.partners==6,"Partner scaling uses at least era one");eras[9]=3;
    a.per_partner[0]=-2;check(query().per_turn.partners==0,"Negative trade-partner trait is ignored");a.per_partner[0]=2;
    options.entries["BALANCE_VP"].value=0;check(query().per_turn.partners==0,"CP option excludes trade-partner bonus");options.entries["BALANCE_VP"].value=1;
    a.per_improvement.clear();rebuild_vp_trait_improvement_types(cities,5);a.historic.clear();a.per_partner.clear();ca.added[0]=3;ca.unimproved[0]=-2;ca.permanent_wltkd[0]=17;a.land_connections[0]=23;
    q=query();check(q.traits==300&&q.unimproved==-200&&q.permanent_wltkd==17&&q.land_connections==23&&q.total_times100==140,"Traits use whole yields while permanent celebration and capital land connections retain hundredths");
    check(capital.we_love_king_turns==0&&q.permanent_wltkd==17&&local().land_connections==0,"Permanent celebration income needs no active celebration; land-connection total belongs to capital");
    a.city_culture=-2;check(query(4).culture==-200&&local(4).culture==-200,"City culture trait applies in every city including negative amounts");
    p.golden_age=true;a.golden_age_tourism=25;vp_city_cached_yields(cities,5,42)[4]=103;capital.yields[4].buildings=999;
    check(query(6).golden_age_tourism==25&&local(6).golden_age_tourism==0,"Golden-age tourism reads cached ordinary capital culture with signed truncation");
    p.golden_age=false;check(query(6).golden_age_tourism==0,"No golden age suppresses tourism conversion");p.golden_age=true;a.golden_age_tourism=-25;check(query(6).golden_age_tourism==-25,"Negative golden-age tourism trait remains active");
    const auto gold=[&]{return vp_city_connection_gold_times100(context,&city);};
    check(vp_city_connection_gold_times100(context,nullptr)==0&&vp_city_connection_gold_times100(context,&capital)==0&&gold()==380,"Connection gold excludes null and capital, then uses separate capital and connected-city populations");
    t.connection_change=2;t.connection_modifier=11;cb.connection_modifier=14;check(gold()==725,"Connection change enters whole gold before player and city percent modifiers");
    t.connection_modifier=-140;check(gold()==-150,"Connection gold can become negative after its positive-base check");
    t.connection_change=-4;check(gold()==0,"Nonpositive connection base returns zero before a negative multiplier could flip it positive");
    t.connection_change=0;t.connection_modifier=0;cb.connection_modifier=0;p.capital=999;check(gold()==0,"No live capital gives zero connection gold");p.capital=42;
    a.connection[1]=2;a.trait_connection[1]=3;cb.connected=true;auto cq=vp_city_connection_yield(context,city,1);
    check(cq.route==1100&&cq.industrial==0&&cq.total_times100==1100,"Route yield keeps player bonus unscaled and scales trait by era");
    cb.industrial=true;cq=vp_city_connection_yield(context,city,1);check(cq.industrial==380&&cq.total_times100==1480,"Industrial connection converts per-city connection gold to production");
    cb.connected=false;cq=vp_city_connection_yield(context,city,1);check(cq.route==0&&cq.industrial==380,"Industrial and ordinary saved connection flags are independent");
    check(vp_city_connection_yield(context,city,0).industrial==0,"Industrial contribution applies only to production");
    options.entries["BALANCE_VP"].value=0;check(vp_city_connection_yield(context,city,1).industrial==0,"CP option disables industrial gold conversion");options.entries["BALANCE_VP"].value=1;
    cb.connected=true;eras[9]=-1;check(vp_city_connection_yield(context,city,1).route==500,"Route trait also uses minimum era one");eras[9]=3;
    ca.added[0]=big;check(query().traits==big*100,"Trait yield exceeds uint32 without truncation");ca.added[0]=0;
    a.per_improvement[big][0]=100;a.improvements_built[big]=big;era={};rebuild_vp_trait_improvement_types(cities,5);check(query().per_turn.improvements==big*100,"Improvement IDs and historic counts have no 32-bit bound");
    a.per_improvement.clear();rebuild_vp_trait_improvement_types(cities,5);t.connection_change=big;check(gold()==380+big*100,"Per-city connection gold uses wide shared treasury state");
    ca.added[0]=INT64_MAX;rejects([&]{query();});ca.added[0]=0;t.connection_change=INT64_MAX;rejects([&]{gold();});t.connection_change=0;
    auto detached=city;rejects([&]{vp_city_trait_yield(context,detached,0);});rejects([&]{vp_city_connection_yield(context,city,99);});
    cities.trade_routes.push_back(route(5,-1));rejects([&]{vp_different_trade_partners(cities,5);});cities.trade_routes.pop_back();
    traits.eras.erase(5);rejects([&]{query();});
}
